import React, { useState } from 'react';
import { ChevronDown, Menu, X, ChevronRight, User, Settings, HelpCircle, LogIn } from 'lucide-react';

const CategoryBar = () => {
  const [isAllMenuOpen, setIsAllMenuOpen] = useState(false);

  const categories = [
    'Fresh',
    'Prime Video',
    'Sell',
    "Today's Deals",
    'Mobile',
    'New Releases',
    'Prime',
    'Amazon Pay',
    'Electronics',
    'Customer Service',
    'Home & Kitchen',
    'Fashion',
    'Computers',
    'Toys & Games'
  ];

  const menuSections = [
    {
      id: 'trending',
      title: 'Trending',
      items: ['Best Sellers', 'New Releases', 'Movers & Shakers']
    },
    {
      id: 'mens-fashion',
      title: "Men's Fashion",
      items: ['Shirts', 'T-Shirts', 'Jeans', 'Jackets', 'Shoes', 'Watches'],
      showSeeAll: true
    },
    {
      id: 'womens-fashion',
      title: "Women's Fashion",
      items: ['Dresses', 'Tops', 'Jeans', 'Jackets', 'Shoes', 'Jewelry'],
      showSeeAll: true
    },
    {
      id: 'programs',
      title: 'Programs & Features',
      items: ['Gift Cards & Mobile Recharges', 'Amazon Launchpad', 'Amazon Business', 'Handloom and Handicrafts'],
      showSeeAll: true
    }
  ];

  const helpSettings = [
    { icon: User, label: 'Your Account' },
    { icon: HelpCircle, label: 'Customer Service' },
    { icon: Settings, label: 'Settings' },
    { icon: LogIn, label: 'Sign in', isHighlighted: true }
  ];

  return (
    <>
      <div className="bg-[#232F3E] text-white shadow-sm relative">
        <div className="max-w-7xl mx-auto px-4">
          <div className="flex items-center h-[38px] space-x-3 overflow-x-auto scrollbar-hide">
            {/* All Menu */}
            <div 
              onClick={() => setIsAllMenuOpen(!isAllMenuOpen)}
              className="flex items-center space-x-1 bg-white/10 hover:bg-white/20 px-3 py-1 rounded cursor-pointer whitespace-nowrap transition-colors border border-white/20"
            >
              <Menu size={18} />
              <span className="text-sm font-bold">All</span>
            </div>

            {/* Categories */}
            {categories.map((category, index) => (
              <div
                key={index}
                className="text-white/90 hover:text-white hover:bg-white/10 px-3 py-1 rounded cursor-pointer whitespace-nowrap text-sm transition-colors border border-transparent hover:border-white/20"
              >
                {category}
              </div>
            ))}

            {/* Trending */}
            <div className="flex items-center text-sm text-white/90 hover:text-white hover:bg-white/10 px-3 py-1 rounded cursor-pointer whitespace-nowrap transition-colors border border-transparent hover:border-white/20">
              <span>Trending</span>
              <ChevronDown size={14} className="ml-1" />
            </div>
          </div>
        </div>
      </div>

      {/* All Menu Flyout */}
      {isAllMenuOpen && (
        <>
          <div 
            className="fixed inset-0 bg-black/50 z-40"
            onClick={() => setIsAllMenuOpen(false)}
          />
          
          <div className="fixed top-0 left-0 h-full w-80 bg-white shadow-2xl z-50 overflow-y-auto animate-slide-in">
            {/* Header */}
            <div className="bg-[#232F3E] text-white p-4 flex items-center space-x-3 sticky top-0 z-10">
              <div className="bg-white/20 p-2 rounded-full">
                <User size={20} />
              </div>
              <div className="flex-1">
                <div className="text-sm text-gray-300">Hello, sign in</div>
                <div className="font-bold">Account & Lists</div>
              </div>
              <button 
                onClick={() => setIsAllMenuOpen(false)}
                className="hover:bg-white/10 p-1 rounded"
              >
                <X size={20} />
              </button>
            </div>

            {/* Menu Sections */}
            <div className="py-2">
              {menuSections.map((section) => (
                <div key={section.id}>
                  <div className="px-4 py-2 hover:bg-gray-100 cursor-pointer flex items-center justify-between border-b border-gray-100">
                    <span className="font-medium">{section.title}</span>
                    <ChevronRight size={16} className="text-gray-400" />
                  </div>
                  <div className="pl-8 py-1 text-sm text-gray-600">
                    {section.items.map((item, idx) => (
                      <div key={idx} className="py-1 hover:text-blue-600 cursor-pointer">
                        {item}
                      </div>
                    ))}
                    {section.showSeeAll && (
                      <div className="py-1 text-blue-600 font-medium cursor-pointer">See all</div>
                    )}
                  </div>
                </div>
              ))}
            </div>

            {/* Help & Settings Section */}
            <div className="border-t border-gray-200 mt-2 pt-2">
              {helpSettings.map((item, index) => {
                const Icon = item.icon;
                return (
                  <div 
                    key={index}
                    className={`px-4 py-2 hover:bg-gray-100 cursor-pointer flex items-center space-x-3 ${index < helpSettings.length - 1 ? 'border-b border-gray-100' : ''}`}
                  >
                    <Icon size={18} className={item.isHighlighted ? 'text-blue-600' : 'text-gray-600'} />
                    <span className={item.isHighlighted ? 'text-blue-600 font-medium' : 'text-gray-700'}>
                      {item.label}
                    </span>
                  </div>
                );
              })}
            </div>
          </div>
        </>
      )}
    </>
  );
};

export default CategoryBar;
